def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    supply = float(day_context['supply'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    alive = []
    for agent_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)

    if budget <= 0:
        return 0

    total_players = 1 + len(alive)
    scarcity_ratio = (total_players * WATER_REQ) / max(1.0, supply)

    prev_bids = []
    urgent_opp_bid = 0
    for opp in alive:
        prev = opp.get('previous_trace', {}) or {}
        bid = prev.get('bid')
        if bid is not None:
            prev_bids.append(float(bid))
            if opp.get('hp', 0) <= 2 or opp.get('no_water_days', 0) >= 1:
                if float(bid) > urgent_opp_bid:
                    urgent_opp_bid = float(bid)

    if hp <= 2 or no_water >= 1:
        base = DAILY_SALARY * 0.92
    elif scarcity_ratio >= 1.8:
        base = DAILY_SALARY * 0.72
    elif scarcity_ratio >= 1.4:
        base = DAILY_SALARY * 0.58
    else:
        base = DAILY_SALARY * 0.42

    if prev_bids:
        highest_prev = max(prev_bids)
        if hp >= 4 and no_water == 0 and highest_prev >= DAILY_SALARY * 0.9:
            bid = DAILY_SALARY * 0.28
        else:
            target = highest_prev + 1.5
            if urgent_opp_bid > 0:
                target = max(target, urgent_opp_bid + 1.5)
            bid = max(base, target)
    else:
        bid = base

    if hp >= 5 and no_water == 0 and scarcity_ratio < 1.2:
        bid = min(bid, DAILY_SALARY * 0.38)

    bid = min(float(budget), max(0.0, bid))
    return bid

