def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 7
    DAILY_SALARY = 80
    EPISODE_DAYS = 10 

    current_day = day_context['day']
    current_supply = day_context['supply']
    my_hp = my_status['hp']
    my_budget = my_status['budget']
    my_no_water_days = my_status['no_water_days']

    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    num_alive_opponents = len(alive_opponents)

    if num_alive_opponents == 0:
        return min(my_budget, 1)

    # 1. Survival mode: If HP is very low or I missed water recently
    if my_hp <= 2 or my_no_water_days >= 1:
        return min(my_budget, DAILY_SALARY * 1.1)

    base_bid = DAILY_SALARY * 0.5 # Start with a moderate bid

    # Calculate total water requirement of all alive agents (including myself)
    total_water_req_alive = WATER_REQ
    for opp in alive_opponents:
        total_water_req_alive += opp['water_requirement']

    # 2. Adjust bid based on supply scarcity
    if current_supply < total_water_req_alive:
        scarcity_factor = total_water_req_alive / current_supply
        base_bid *= min(1.5, scarcity_factor * 0.8)
    elif current_supply >= total_water_req_alive * 1.5:
        base_bid *= 0.8

    # 3. Adjust bid based on number of opponents
    if num_alive_opponents > 1:
        base_bid *= 1.1
    elif num_alive_opponents == 1:
        base_bid *= 1.05

    # 4. Analyze yesterday's bids from opponents (if available)
    yesterday_bids = []
    for opp in alive_opponents:
        prev_trace = opp.get('previous_trace', {})
        if prev_trace and prev_trace.get('bid') is not None:
            yesterday_bids.append(prev_trace['bid'])

    if yesterday_bids:
        max_yesterday_bid = max(yesterday_bids)
        avg_yesterday_bid = sum(yesterday_bids) / len(yesterday_bids)

        if max_yesterday_bid >= DAILY_SALARY * 0.8:
            base_bid = max(base_bid, max_yesterday_bid + 5)
        elif max_yesterday_bid > 0:
            base_bid = max(base_bid, avg_yesterday_bid * 1.05)

    # 5. End game considerations
    remaining_days = EPISODE_DAYS - current_day
    if remaining_days <= 3:
        if my_budget / (remaining_days + 1) > DAILY_SALARY * 1.2:
            base_bid = max(base_bid, DAILY_SALARY * 0.9)
        elif my_budget < DAILY_SALARY * 0.7 and my_hp > 2:
            base_bid = min(base_bid, DAILY_SALARY * 0.6)

    final_bid = max(1, min(my_budget, base_bid))

    return final_bid

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 8
    DAILY_SALARY = 140
    supply = int(day_context['supply'])
    hp = my_status['hp']
    budget = my_status['budget']
    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    if not alive_opponents:
        return min(budget, DAILY_SALARY * 0.4)

    # Look at yesterday's opponent bids
    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    # Base bid from urgency and supply
    if hp <= 2:
        base_bid = DAILY_SALARY * 0.9
    elif hp <= 4:
        base_bid = DAILY_SALARY * 0.7
    else:
        base_bid = DAILY_SALARY * 0.5

    # Adjust for supply scarcity
    if supply < 18:
        base_bid = min(base_bid, DAILY_SALARY * 0.85)

    # If yesterday's highest bid is known, adjust to beat it slightly if necessary
    if yesterday_bids:
        max_prev = max(yesterday_bids)
        if max_prev > base_bid and hp <= 3:
            # Need to outbid to survive
            bid = min(budget, max_prev + 1.0)
        elif max_prev > base_bid:
            # Not desperate, save money
            bid = min(budget, base_bid)
        else:
            bid = min(budget, base_bid)
    else:
        bid = min(budget, base_bid)

    return max(bid, 0.0)
